"""AnKing AN04: traduções com âncoras editoriais em negrito; revisão 11/11."""
AK = {
 1481418712049: (11, 'O núcleo do tálamo que recebe a <b>informação visual</b> do trato óptico é o corpo geniculado {{c1::lateral}}', 'Lateral = eye (higher), medial = ear (lower), as the professor says.'),
 1481418725172: (11, 'O núcleo do tálamo que recebe a <b>informação auditiva</b> do colículo inferior é o corpo geniculado {{c1::medial}}', 'It projects to the primary auditory cortex in the temporal lobe.'),
 1461884702127: (14, '<b>ADH e ocitocina</b> são produzidos em neurônios do hipotálamo e liberados na {{c1::neuro-hipófise}}', 'The axons run down the infundibulum (hypothalamo-hypophyseal tract).'),
 1481562846112: (14, 'Na síndrome de <b>Wernicke-Korsakoff</b> há lesão bilateral dos {{c1::corpos mamilares}}', 'Thiamine deficiency in alcohol use; the mammillary bodies sit in the floor of the hypothalamus.'),
 1481244778741: (14, 'Lesão do <b>quiasma óptico</b> (adenoma de hipófise, craniofaringioma) causa hemianopsia {{c1::bitemporal}}', 'The crossing nasal fibers carry the temporal visual fields.'),
 1481944929569: (14, 'O tumor que comprime o <b>quiasma óptico</b> em crianças, com hemianopsia bitemporal, é o {{c1::craniofaringioma}}', 'It arises from Rathke pouch remnants above the sella.'),
 1481418766004: (16, 'O núcleo {{c1::supraquiasmático}} do <b>hipotálamo</b> regula o {{c2::ritmo circadiano}}', 'It lies above the optic chiasm and receives light input from the retina.'),
 1481418757045: (16, 'O núcleo {{c1::supraóptico}} do hipotálamo produz principalmente <b>ADH</b>', 'Both supraoptic and paraventricular nuclei make ADH and oxytocin, each mainly one.'),
 1481418763459: (16, 'O núcleo {{c1::paraventricular}} do hipotálamo secreta principalmente <b>ocitocina</b>', 'It also makes CRH and TRH.'),
 1481418777586: (16, 'A área {{c1::ventromedial}} do <b>hipotálamo</b> é responsável pela {{c2::saciedade}}', 'Its lesion causes hyperphagia; leptin stimulates it.'),
 1481418800702: (16, 'O hipotálamo {{c1::anterior}} percebe o calor e coordena a <b>perda de calor</b>', 'Lesion causes hyperthermia.'),
 1481418808669: (16, 'O hipotálamo {{c1::posterior}} percebe o frio e coordena a <b>conservação de calor</b>', 'Lesion causes poikilothermia.'),
 1481418839841: (18, 'O {{c2::epitálamo}} é formado pela glândula {{c1::pineal}} e pelos <b>núcleos da habênula</b>', 'It lies at the back of the diencephalon, above the hypothalamic sulcus.'),
 1481418842065: (18, 'A glândula {{c2::pineal}} secreta {{c1::melatonina}} e regula o <b>ritmo circadiano</b>', 'The suprachiasmatic nucleus drives it through sympathetic fibers.'),
 1481162464655: (20, 'O <b>hemibalismo</b> resulta de lesão do núcleo {{c1::subtalâmico}} do lado {{c2::contralateral}}', 'The subthalamic nucleus is the motor nucleus of the subthalamus; lacunar stroke is the usual cause.'),
 1481513119712: (28, 'O <b>giro</b> {{c1::pré}}-central é a área do córtex {{c2::motor primário}}', 'Upper motor neurons of the corticospinal tract start here.'),
 1481513311304: (30, 'O <b>centro motor da fala</b> é a área de {{c1::Broca}}', 'Its lesion gives nonfluent speech with preserved comprehension.'),
 1481513127112: (31, 'O <b>giro</b> {{c1::pós}}-central é a área do córtex {{c2::somestésico primário}}', 'Sensory pathways from the thalamus reach it.'),
 1481596931776: (37, 'O <b>giro do cíngulo</b> é limitado superiormente pelo sulco do {{c1::cíngulo}}', 'It runs parallel to the callosal sulcus; the cingulate gyrus lies between them.'),
 1481596917147: (39, 'Qual sulco a seta indica? {{c1::Sulco parietoccipital}}', 'It separates parietal and occipital lobes on the medial surface.'),
 1481244690823: (39, 'O <b>córtex visual primário</b> fica nos giros {{c1::cúneo}} (acima) e {{c1::lingual}} (abaixo), separados pelo sulco {{c2::calcarino}}', 'Fibers of the inferior retina end in the lingual gyrus, superior retina in the cuneus.'),
 1481162002789: (43, 'A parte do encéfalo que modula o <b>movimento esquelético</b> é o conjunto dos {{c1::núcleos da base}}', 'They act through the thalamus on the motor cortex.'),
 1481162303980: (45, 'O <b>núcleo</b> {{c1::lentiforme}} é formado pelo {{c2::putâmen}} e pelo {{c3::globo pálido}}', "The lesson's corpus striatum adds the caudate nucleus to it."),
 1481857900096: (45, 'Na doença de {{c3::Huntington}} <b>degeneram neurônios</b> {{c1::GABAérgicos}} do núcleo {{c2::caudado}} e do putâmen', 'Caudate atrophy enlarges the lateral ventricles on imaging.'),
 1481857835449: (45, 'Na doença de {{c3::Parkinson}} <b>degeneram neurônios</b> {{c1::dopaminérgicos}} da {{c2::substância negra}}', 'The substantia nigra projects to the striatum.'),
 1480389641277: (46, 'As <b>fibras corticoespinais</b> descem pela perna {{c2::posterior}} da {{c1::cápsula interna}}', 'A small lacunar infarct there gives pure motor hemiparesis.'),
 1522347007612: (47, 'As <b>artérias</b> {{c3::vertebrais}} sobem pelos forames {{c2::transversos}} e podem ser lesadas no {{c1::trauma cervical}}', 'Hence their injury in cervical trauma (dissection).'),
 1520976098044: (47, 'O <b>roubo da subclávia</b> ocorre por estenose proximal à origem da artéria {{c1::vertebral}}', 'Blood flows backwards in the vertebral artery to the arm, causing vertebrobasilar insufficiency.'),
 1480995212247: (48, 'A artéria que irriga o <b>bulbo lateral</b> é a {{c1::cerebelar inferior posterior}}', 'Its occlusion causes lateral medullary (Wallenberg) syndrome.'),
 1480995292746: (48, 'A <b>síndrome</b> {{c2::bulbar lateral}} (Wallenberg) decorre da oclusão da artéria {{c1::cerebelar inferior posterior}} ou da {{c3::vertebral}}', 'Vertebral dissection is a common cause in the young.'),
 1480995205801: (48, 'O <b>bulbo medial</b> é irrigado pela artéria espinal anterior e pela artéria {{c1::vertebral}}', 'Medial medullary syndrome affects pyramid, medial lemniscus and XII.'),
 1480995225262: (48, 'A artéria que irriga a <b>ponte lateral</b> é a {{c1::cerebelar inferior anterior}}', 'Its occlusion causes lateral pontine syndrome.'),
 1480995329569: (48, 'A <b>síndrome</b> {{c2::pontina lateral}} decorre da oclusão da artéria {{c1::cerebelar inferior anterior}}', 'It includes facial palsy and hearing loss on the same side.'),
 1480995218951: (50, 'A <b>ponte medial</b> é irrigada pelos ramos paramedianos da artéria {{c1::basilar}}', 'These are the pontine branches of the basilar artery.'),
 1480995318517: (50, 'A <b>síndrome</b> {{c2::pontina medial}} decorre da oclusão de ramos paramedianos da artéria {{c1::basilar}}', 'It affects corticospinal tract and VI.'),
 1481836504722: (50, 'A <b>síndrome do encarceramento</b> (locked-in) costuma ser causada por AVC da artéria {{c1::basilar}}', 'Ventral pons infarct spares consciousness.'),
 1481836514209: (50, 'Na <b>síndrome do encarceramento</b>, o paciente ainda move os olhos na {{c1::vertical}} e pisca', 'The vertical gaze centres in the midbrain are spared.'),
 1550673159267: (50, 'O <b>nervo oculomotor</b> passa entre a artéria cerebelar {{c2::superior}} e a cerebral {{c2::posterior}} e pode ser comprimido por aneurisma da comunicante {{c1::posterior}}', 'A dilated pupil is the first sign.'),
 1480995234166: (51, 'O <b>mesencéfalo</b> é irrigado sobretudo pela artéria {{c1::cerebral posterior}}', 'Its paramedian branches supply the cerebral peduncle and III.'),
 1481047476591: (51, 'A <b>síndrome de Weber</b> (mesencéfalo medial) decorre da oclusão de ramos {{c2::paramedianos}} da artéria {{c1::cerebral posterior}}', 'III palsy on the same side and hemiparesis on the opposite side.'),
 1481513222026: (51, 'A artéria cerebral que irriga o <b>lobo occipital</b> é a {{c1::cerebral posterior}}', 'The visual cortex lies in the occipital lobe.'),
 1481513227002: (51, 'A artéria cerebral que irriga a face inferior do <b>lobo temporal</b> é a {{c1::cerebral posterior}}', 'This matches the inferior surface the professor assigns to the PCA.'),
 1481244840641: (51, 'A <b>oclusão da artéria cerebral posterior</b> causa hemianopsia homônima contralateral com {{c1::preservação macular}}', 'The macular cortex also receives MCA collaterals.'),
 1481513158967: (55, 'A <b>parte lateral</b> dos giros pré e pós-central é irrigada pela artéria {{c1::cerebral média}}', 'The face and upper limb areas lie there.'),
 1481562751403: (55, '<b>AVC</b> da artéria cerebral {{c3::média}} causa paralisia e perda sensitiva {{c2::contralaterais}} da {{c1::face}} e do {{c1::membro superior}}', 'The leg area on the medial surface is spared.'),
 1481562763561: (55, 'AVC da artéria cerebral {{c2::média}} no hemisfério {{c1::dominante}} pode causar <b>afasia</b>', 'Broca and Wernicke areas lie in the MCA territory.'),
 1481562772354: (55, 'AVC da artéria cerebral {{c2::média}} no <b>hemisfério não dominante</b> pode causar {{c1::heminegligência}}', 'The right parietal lobe is usually involved.'),
 1481562774888: (55, '<b>AVC</b> das artérias {{c1::lenticuloestriadas}} causa paralisia e perda sensitiva de todo o hemicorpo {{c2::contralateral}}', 'These deep MCA branches supply the striatum and internal capsule.'),
 1483845113686: (55, 'AVC das <b>artérias lenticuloestriadas</b> atinge o estriado e a {{c1::cápsula interna}}', 'Small deep (lacunar) infarcts.'),
 1481513164343: (56, 'A <b>parte medial</b> dos giros pré e pós-central é irrigada pela artéria {{c1::cerebral anterior}}', 'The leg area lies there (paracentral lobule).'),
 1481562744652: (56, '<b>AVC</b> da artéria cerebral {{c2::anterior}} causa paralisia e perda sensitiva do membro {{c1::inferior}} {{c3::contralateral}}', 'The leg area is on the medial surface.'),
 1481772047979: (58, 'Aneurisma da comunicante {{c1::anterior}} pode comprimir o <b>quiasma óptico</b>', 'The anterior communicating artery lies just in front of the chiasm.'),
 1481772053364: (58, 'Aneurisma da comunicante {{c1::posterior}} pode comprimir o <b>nervo oculomotor</b>', 'The pupil dilates first because parasympathetic fibers are peripheral.'),
}

# 11/11: complementos diretamente exigidos pelas provas novas.
AK.update({1481418744155: (12, '<div data-nebli-organizacao="true">Após <b>AVC</b> {{c1::talâmico}}, surge déficit sensitivo {{c2::contralateral}}. Semanas a meses depois:<br><br>Sensibilidade desagradável: {{c3::disestesia}}<br>Dor a estímulo inócuo: {{c4::alodinia}}<br>Dor aumentada a estímulo doloroso: {{c4::hiperalgesia}}</div>', 'Thalamic somatosensory relays receive crossed body input. Central pain may develop weeks to months after the initial sensory loss; corticospinal fibers do not traverse the thalamus.'), 1481244817525: (39, 'Lesão da <b>alça de Meyer</b>, no lobo temporal, causa {{c1::quadrantanopsia homônima superior}} contralateral.', 'Inferior retinal fibers representing the superior visual field course through the temporal lobe. A left temporal lesion therefore affects the right superior visual quadrant.'), 1481857859641: (45, '<div data-nebli-organizacao="true">Sinais motores da <b>doença de Parkinson</b>:<br><br>Tremor de {{c1::repouso}}<br>{{c1::Rigidez}} muscular<br>{{c1::Bradicinesia}}<br>Instabilidade {{c1::postural}}<br>Marcha {{c1::arrastada}}<br>Letra pequena: {{c1::micrografia}}</div>', 'Loss of nigrostriatal dopamine reduces facilitation of movement. Rest tremor contrasts with the action tremor of cerebellar disease; rigidity is plastic rather than velocity dependent spasticity.'), 1481162319275: (45, 'A via {{c1::direta}} dos <b>núcleos da base</b> facilita o movimento.', 'Striatal inhibition of GPi reduces its tonic inhibition of the thalamus, increasing thalamocortical excitation.'), 1481162335806: (45, 'Na <b>via direta</b>, o estriado {{c2::inibe}} o {{c1::globo pálido interno}}.', 'GABAergic striatal neurons suppress the tonic inhibitory output from GPi to the motor thalamus.'), 1481162353700: (45, 'Na <b>via direta</b>, a {{c1::inibição}} do globo pálido interno desinibe o núcleo {{c2::ventral lateral}} do tálamo.', 'Removing pallidal inhibition permits greater thalamic excitation of motor cortex; this is disinhibition, not a direct excitatory striatothalamic connection.'), 1481162368568: (45, 'A via {{c1::indireta}} dos <b>núcleos da base</b> reduz o movimento.', 'The indirect route ultimately increases GPi inhibition of the motor thalamus. Interrupting this brake can cause hyperkinetic movement.'), 1481162377083: (45, 'Na <b>via indireta</b>, o estriado {{c2::inibe}} o {{c1::globo pálido externo}}.', 'GPe normally inhibits the subthalamic nucleus; inhibiting GPe releases that nucleus from inhibition.'), 1481162387832: (45, 'Na <b>via indireta</b>, inibir o globo pálido externo causa {{c2::excitação}} do núcleo {{c1::subtalâmico}}.', 'This is disinhibition: reduced GABAergic pallidal input allows the subthalamic nucleus to become more active.'), 1481162400975: (45, 'Na <b>via indireta</b>, o núcleo subtalâmico {{c2::excita}} o {{c1::globo pálido interno}}.', 'Glutamatergic subthalamic input increases the inhibitory pallidal output to the motor thalamus.'), 1481162415359: (45, 'Na <b>via indireta</b>, a {{c1::excitação}} do globo pálido interno inibe o núcleo {{c2::ventral lateral}} do tálamo.', 'Greater pallidal inhibition reduces thalamocortical excitation and suppresses movement.'), 1481162430216: (45, 'A <b>dopamina</b> estimula a via {{c1::direta}} por receptores {{c2::D1}}.', 'D1 activation facilitates the movement promoting route. Without this drive, the relative inhibitory influence of the indirect route rises.'), 1481162436810: (45, 'A <b>dopamina</b> inibe a via {{c1::indireta}} por receptores {{c2::D2}}.', 'Suppressing the movement reducing route also facilitates movement; dopamine thus promotes movement through both receptor populations.')})

AK.update({
 1483930154512: (21, '<div data-nebli-organizacao="true">No <b>circuito de Papez</b>:<br><br>Fórnix: hipocampo → {{c1::corpos mamilares}}<br>Fascículo <b>mamilotalâmico</b>: corpos mamilares → {{c1::tálamo anterior}}<br>Do tálamo anterior: → {{c1::giro do cíngulo}} → córtex entorrinal → hipocampo</div>', 'This limbic circuit contributes to episodic memory and emotional processing. Mammillary bodies project through the mammillothalamic tract to the anterior thalamic nuclei; these relay to the cingulate gyrus, which connects through the cingulum to the entorhinal region. The fornix links the hippocampal formation to the mammillary bodies.'),
 1481562800018: (41, 'Hipocampo, amígdala, fórnix, corpos mamilares e <b>giro do cíngulo</b> integram o sistema {{c1::límbico}}.', 'The parahippocampal gyrus and cingulate gyrus form the cortical limbic ring. Colliculi are midbrain reflex centers and are not components of the classic Papez circuit.')
})

AK[1483930154512] = (AK[1483930154512][0], AK[1483930154512][1].replace('</div>', '<br>Função <b>mnésica</b>: {{c1::memória episódica}}</div>'), AK[1483930154512][2])
AK[1481562800018] = (AK[1481562800018][0], AK[1481562800018][1].replace('e <b>giro do cíngulo</b>', ', <b>giro do cíngulo</b> e giro para-hipocampal'), AK[1481562800018][2])

AK[1483930154512] = (21, '<div data-nebli-organizacao="true">No <b>circuito de Papez</b>:<br><br>Fórnix: hipocampo → {{c1::corpos mamilares}}<br>Fascículo <b>mamilotalâmico</b>: {{c1::corpos mamilares}} → {{c1::tálamo anterior}}<br>Próxima estação <b>cortical</b>: {{c1::giro do cíngulo}}<br>Função <b>mnésica</b>: {{c1::memória episódica}}</div>', AK[1483930154512][2])
